# Wilson 95% confidence interval for a proportion. Better than the normal
# approximation when p is near 0 or 1, which is exactly our situation.
def wilson(k,n,z=1.96):
    if n==0: return (0.0,0.0)
    p=k/n; den=1+z*z/n
    ctr=(p+z*z/(2*n))/den
    half=z*np.sqrt(p*(1-p)/n+z*z/(4*n*n))/den
    return (ctr-half, ctr+half)

